/* date picker and range picker */
.dp{width:100%;max-width:330px;padding:12px}
.dp-sel{display:grid;grid-template-columns:.8fr 1.3fr 1fr;gap:6px}
.dp-s{position:relative;padding:0}
.dp-s select{padding:8px 26px 8px 10px;font-family:var(--sans);font-size:13px;width:100%}
.dp-s .ms{position:absolute;right:7px;top:50%;transform:translateY(-50%);width:1em;color:var(--muted);pointer-events:none;font-size:15px}
.dp-s:focus-within{border-color:var(--accent-icon-line)}
.dp-val{margin:8px 0 12px;text-transform:none}
.dp-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
.dp-head .t{font-weight:600;font-size:14px}
.dp-head .ib{width:28px;height:28px}
.dp-dow{display:grid;grid-template-columns:repeat(7,1fr);text-align:center;font-size:10px;margin-bottom:4px}
.dp-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;transition:opacity .2s ease,transform .3s var(--ease)}
.dp-grid.out-l{opacity:0;transform:translateX(-14px)}
.dp-grid.out-r{opacity:0;transform:translateX(14px)}
.dd{position:relative;height:36px;display:grid;place-items:center;font-size:13px;color:var(--text);transition:background-color .2s,color .2s}
.dd:hover{background:rgba(var(--fg-rgb),.05)}
.dd.mute{color:var(--muted);opacity:.5}
.dd.wk{color:var(--text-dim)}
.dd.today{box-shadow:inset 0 0 0 1px var(--accent-icon-line)}
.dd.today::after{content:"";position:absolute;bottom:5px;width:4px;height:4px;background:var(--accent)}
.dd.sel,.dd.r-s,.dd.r-e{background:var(--accent-hi);color:#120a02;font-weight:600}
.dd.sel::after,.dd.r-s::after,.dd.r-e::after{background:#120a02}
.dd.r-in{background:var(--accent-bg);color:var(--text)}
.dd.mute.r-s,.dd.mute.r-e{opacity:1}
.dd.mute.r-in{opacity:.85}
.dd.r-pv{background:rgba(var(--fg-rgb),.05)}
.dd:focus-visible{outline:1px solid var(--accent);outline-offset:-1px}
.dp-foot{display:flex;justify-content:space-between;margin-top:10px}
.rp{width:100%;max-width:470px}
.rp-body{display:grid;grid-template-columns:130px 1fr}
.rp-presets{display:flex;flex-direction:column;padding:10px 8px;border-right:1px solid var(--line);gap:2px}
.rp-pre{padding:8px 10px;text-align:left;font-size:13px;color:var(--text-dim);transition:color .2s,background-color .2s}
.rp-pre:hover{color:var(--text);background:rgba(var(--fg-rgb),.03)}
.rp-pre.on{color:var(--accent);background:var(--accent-bg)}
.rp-cal{padding:12px}
.rp .dd{height:32px}
.rp-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 14px;border-top:1px solid var(--line);font-size:13px}
.rp-foot .btn{padding:8px 14px;font-size:13px}

/* ---------- date picker ---------- */
{
  const grid = $('#dp-grid'), val = $('#dp-val'), mlab = $('#dp-month'), sd = $('#dp-d'), sm = $('#dp-m'), sy = $('#dp-y');
  let vy = TODAY.getFullYear(), vm = TODAY.getMonth(), sel = null, focus = TODAY;
  const MONTHS = Array.from({ length:12 }, (_, i) => new Date(2026, i, 1).toLocaleDateString('en-GB', { month:'long' }));
  sm.innerHTML = MONTHS.map((n, i) => `<option value="${i}">${n}</option>`).join('');
  sy.innerHTML = Array.from({ length:11 }, (_, i) => TODAY.getFullYear() - 5 + i).map(y => `<option value="${y}">${y}</option>`).join('');
  function syncSelects(){
    const days = new Date(vy, vm + 1, 0).getDate();
    sd.innerHTML = '<option value="">Day</option>' + Array.from({ length:days }, (_, i) => `<option value="${i + 1}">${i + 1}</option>`).join('');
    sd.value = sel && sel.getMonth() === vm && sel.getFullYear() === vy ? String(sel.getDate()) : '';
    sm.value = String(vm); sy.value = String(vy);
  }
  function build(){
    mlab.textContent = new Date(vy, vm, 1).toLocaleDateString('en-GB', { month:'long', year:'numeric' });
    grid.innerHTML = monthCells(vy, vm).map(d => {
      const cls = ['dd', d.getMonth() !== vm ? 'mute' : '', (d.getDay() % 6 === 0) ? 'wk' : '', dayKey(d) === dayKey(TODAY) ? 'today' : '', sel && dayKey(d) === dayKey(sel) ? 'sel' : ''].join(' ');
      return `<button class="${cls}" data-k="${d.getTime()}" tabindex="${dayKey(d) === dayKey(focus) ? 0 : -1}" aria-label="${d.toDateString()}">${d.getDate()}</button>`;
    }).join('');
    syncSelects();
  }
  function slide(dir, after){
    grid.classList.add(dir > 0 ? 'out-l' : 'out-r');
    setTimeout(() => { after(); build(); grid.style.transition = 'none'; grid.classList.remove('out-l', 'out-r'); grid.classList.add(dir > 0 ? 'out-r' : 'out-l'); grid.offsetWidth; grid.style.transition = ''; grid.classList.remove('out-l', 'out-r'); }, 180);
  }
  function goTo(y, m){ if (y === vy && m === vm) return build(); const dir = (y * 12 + m) > (vy * 12 + vm) ? 1 : -1; slide(dir, () => { vy = y; vm = m; }); }
  const move = n => { const nm = vm + n; goTo(vy + Math.floor(nm / 12), ((nm % 12) + 12) % 12); Sound.play('tab'); };
  $('#dp-prev').addEventListener('click', () => move(-1)); $('#dp-next').addEventListener('click', () => move(1));
  function pick(d){
    sel = d; focus = d; swapText(val, d.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' })); Sound.play('select');
    goTo(d.getFullYear(), d.getMonth());
  }
  grid.addEventListener('click', e => { const b = e.target.closest('.dd'); if (b) pick(new Date(+b.dataset.k)); });
  grid.addEventListener('keydown', e => {
    const map = { ArrowLeft:-1, ArrowRight:1, ArrowUp:-7, ArrowDown:7 };
    if (map[e.key] != null){ e.preventDefault(); focus = addDays(focus, map[e.key]); Sound.play('tick');
      const go = () => { const b = $(`.dd[data-k="${focus.getTime()}"]`, grid); if (b) b.focus(); };
      if (focus.getMonth() !== vm || focus.getFullYear() !== vy){ goTo(focus.getFullYear(), focus.getMonth()); setTimeout(go, 220); } else { build(); go(); } }
    else if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); pick(focus); setTimeout(() => { const b = $(`.dd[data-k="${focus.getTime()}"]`, grid); if (b) b.focus(); }, 230); }
  });
  sd.addEventListener('change', () => { if (sd.value) pick(new Date(vy, vm, +sd.value)); });
  function fromSelects(){
    const y = +sy.value, m = +sm.value;
    if (sel){ const day = Math.min(sel.getDate(), new Date(y, m + 1, 0).getDate()); sel = new Date(y, m, day); focus = sel; swapText(val, sel.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' })); }
    goTo(y, m); Sound.play('tab');
  }
  sm.addEventListener('change', fromSelects); sy.addEventListener('change', fromSelects);
  $('#dp-today').addEventListener('click', () => pick(TODAY));
  $('#dp-clear').addEventListener('click', () => { sel = null; swapText(val, 'No date selected'); build(); Sound.play('tick'); });
  build();
}
